package ru.artem.beforethefall.equipment;
import org.bukkit.ChatColor;import org.bukkit.Material;import org.bukkit.NamespacedKey;import org.bukkit.inventory.ItemStack;import org.bukkit.inventory.ShapedRecipe;import org.bukkit.inventory.ShapelessRecipe;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.PersistentDataType;import ru.artem.beforethefall.BeforeTheFallPlugin;import java.util.List;
public final class SurvivalCraftingManager {
 private final BeforeTheFallPlugin plugin;public SurvivalCraftingManager(BeforeTheFallPlugin p){plugin=p;}
 public void register(){
  ShapedRecipe mask=new ShapedRecipe(key("craft_gas_mask"),plugin.getGasMaskManager().createMask());mask.shape("LGL","IRI"," L ");mask.setIngredient('L',Material.LEATHER);mask.setIngredient('G',Material.GLASS_PANE);mask.setIngredient('I',Material.IRON_INGOT);mask.setIngredient('R',Material.IRON_BARS);add(mask);
  ShapedRecipe dosimeter=new ShapedRecipe(key("craft_dosimeter"),plugin.getDosimeterManager().createDosimeter());
  dosimeter.shape("GCG","RIR"," G ");
  dosimeter.setIngredient('G',Material.GLASS_PANE);
  dosimeter.setIngredient('C',Material.CLOCK);
  dosimeter.setIngredient('R',Material.REDSTONE);
  dosimeter.setIngredient('I',Material.IRON_INGOT);
  add(dosimeter);
  ShapedRecipe filter=new ShapedRecipe(key("craft_filter"),plugin.getGasMaskManager().createFilter());filter.shape("PCP","RIR","PCP");filter.setIngredient('P',Material.PAPER);filter.setIngredient('C',Material.CHARCOAL);filter.setIngredient('I',Material.IRON_INGOT);filter.setIngredient('R',Material.REDSTONE);add(filter);ShapelessRecipe filterFlexible=new ShapelessRecipe(key("craft_filter_shapeless"),plugin.getGasMaskManager().createFilter());filterFlexible.addIngredient(4,Material.PAPER);filterFlexible.addIngredient(2,Material.CHARCOAL);filterFlexible.addIngredient(2,Material.REDSTONE);filterFlexible.addIngredient(Material.IRON_INGOT);add(filterFlexible);
  ShapedRecipe nugget=new ShapedRecipe(key("craft_filter_iron_nugget"),plugin.getGasMaskManager().createFilter());nugget.shape("PCP","RNR","PCP");nugget.setIngredient('P',Material.PAPER);nugget.setIngredient('C',Material.CHARCOAL);nugget.setIngredient('N',Material.IRON_NUGGET);nugget.setIngredient('R',Material.REDSTONE);add(nugget);
  ItemStack medicine=new ItemStack(Material.POTION);ItemMeta medMeta=medicine.getItemMeta();medMeta.setDisplayName(ChatColor.GREEN+"Антирадиационный препарат");medMeta.setLore(List.of(ChatColor.GRAY+"Ускоряет снижение накопленной дозы",ChatColor.GRAY+"Вызывает лёгкую слабость на короткое время"));medMeta.getPersistentDataContainer().set(new NamespacedKey(plugin,"radiation_medicine"),PersistentDataType.BYTE,(byte)1);medicine.setItemMeta(medMeta);ShapedRecipe med=new ShapedRecipe(key("craft_radiation_medicine"),medicine);med.shape(" G ","RPH"," G ");med.setIngredient('G',Material.GOLDEN_CARROT);med.setIngredient('R',Material.REDSTONE);med.setIngredient('P',Material.POTION);med.setIngredient('H',Material.HONEY_BOTTLE);add(med);
  ItemStack charge=new ItemStack(Material.TNT);ItemMeta cm=charge.getItemMeta();cm.setDisplayName(ChatColor.DARK_RED+"Ядерный заряд");cm.setItemModel(new NamespacedKey(plugin, "nuclear_bomb"));cm.setLore(List.of(ChatColor.GRAY+"Поставь как блок TNT",ChatColor.GRAY+"Подожги огнивом или активируй редстоун"));cm.getPersistentDataContainer().set(new NamespacedKey(plugin,"atomic_charge"),PersistentDataType.BYTE,(byte)1);charge.setItemMeta(cm);ShapedRecipe nuke=new ShapedRecipe(key("craft_nuclear_charge"),charge);nuke.shape("URU","TCT","URU");nuke.setIngredient('U',Material.GOLD_INGOT);nuke.setIngredient('R',Material.REDSTONE_BLOCK);nuke.setIngredient('T',Material.TNT);nuke.setIngredient('C',Material.CLOCK);add(nuke);
  ItemStack core=new ItemStack(Material.LODESTONE);ItemMeta bm=core.getItemMeta();bm.setDisplayName(ChatColor.DARK_AQUA+"Магнетит — ядро бункера");bm.setLore(List.of(ChatColor.GRAY+"Крафтовое ядро системы защиты",ChatColor.YELLOW+"Обычный магнетит не активирует бункер"));bm.getPersistentDataContainer().set(new NamespacedKey(plugin,"atomic_bunker_core"),PersistentDataType.BYTE,(byte)1);core.setItemMeta(bm);ShapedRecipe bunker=new ShapedRecipe(key("craft_bunker_core"),core);bunker.shape("OIO","IRI","OIO");bunker.setIngredient('O',Material.OBSIDIAN);bunker.setIngredient('I',Material.IRON_BLOCK);bunker.setIngredient('R',Material.REDSTONE_BLOCK);add(bunker);
  var suit=plugin.getProtectiveSuitManager();ShapedRecipe helmet=new ShapedRecipe(key("craft_radiation_helmet"),suit.createPiece(Material.LEATHER_HELMET,"шлем"));helmet.shape("LYL","L L","   ");helmet.setIngredient('L',Material.LEATHER);helmet.setIngredient('Y',Material.YELLOW_DYE);add(helmet);ShapedRecipe chest=new ShapedRecipe(key("craft_radiation_chestplate"),suit.createPiece(Material.LEATHER_CHESTPLATE,"нагрудник"));chest.shape("L L","LYL","L L");chest.setIngredient('L',Material.LEATHER);chest.setIngredient('Y',Material.YELLOW_DYE);add(chest);ShapedRecipe legs=new ShapedRecipe(key("craft_radiation_leggings"),suit.createPiece(Material.LEATHER_LEGGINGS,"штаны"));legs.shape("LYL","L L","L L");legs.setIngredient('L',Material.LEATHER);legs.setIngredient('Y',Material.YELLOW_DYE);add(legs);ShapedRecipe boots=new ShapedRecipe(key("craft_radiation_boots"),suit.createPiece(Material.LEATHER_BOOTS,"ботинки"));boots.shape("   ","L L","L L");boots.setIngredient('L',Material.LEATHER);add(boots);
 }
 private NamespacedKey key(String s){return new NamespacedKey(plugin,s);}private void add(ShapedRecipe r){plugin.getServer().removeRecipe(r.getKey());if(!plugin.getServer().addRecipe(r))plugin.getLogger().warning("Could not register crafting recipe: "+r.getKey());}private void add(ShapelessRecipe r){plugin.getServer().removeRecipe(r.getKey());if(!plugin.getServer().addRecipe(r))plugin.getLogger().warning("Could not register crafting recipe: "+r.getKey());}
}